import numpy as np
km=np.array([1.,2.,3.,4.5,6.])
minutes=np.array([18.,25.,34.,44.,55.])
def loss(w): return np.mean((w*km-minutes)**2)
def grad(w): return np.mean(2*(w*km-minutes)*km)
diagnostics={}
def descend(lr,tol=1e-6,max_steps=10000):
    w,prev=0.,loss(0.)
    trace=[]
    for step in range(1,max_steps+1):
        w=w-lr*grad(w)
        cur=loss(w)
        delta=abs(prev-cur)
        gradient=grad(w)
        trace.append({"w":w,"gradient":gradient,"mse":cur,"loss_change":delta})
        if delta<tol:
            reason="small_step_not_minimum" if abs(gradient)>1e-3 else "loss_change"
            diagnostics[lr]={"gradient":gradient,"loss_change":delta,"reason":reason,"history":trace}
            return w,step
        prev=cur
    diagnostics[lr]={"gradient":grad(w),"loss_change":delta,"reason":"max_steps","history":trace}
    return w,max_steps
steps={};w_found={}
for lr in [.001,.01,.03]:
    w,n=descend(lr);steps[lr]=n;w_found[lr]=round(w,4)
with np.errstate(all="ignore"):
    w_01,steps_01=descend(.1)
small_w,small_steps=descend(1e-12)
stop_diagnostics=diagnostics[1e-12]
print(steps,w_found,steps_01,w_01)
print(stop_diagnostics)

